def copy_existing(apps, schema_editor):
    """Existing texts move into the per-language descriptions; pets follow the amenity list."""
    Cottage = apps.get_model("owners", "Cottage")
    for c in Cottage.objects.all():
        texts = {}
        if c.description_en.strip():
            texts["en"] = c.description_en
        if c.description_fi.strip():
            texts["fi"] = c.description_fi
        c.descriptions = texts
        c.pets_allowed = "pets" in (c.amenities or [])
        c.updated_at = c.created_at
        c.save(update_fields=["descriptions", "pets_allowed", "updated_at"])


